for _ in range(int(input())):
	n = int(input())
	s = list(input().strip())
	lw = -2
	if n == 1:
		if s[0] == '0':
			print(1)
			continue
		else:
			print(0)
			continue
	elif n == 2:
		if s[0] == s[1] == '0':
			print(1)
			continue
		else:
			print(0)
			continue
	count = 0
	for i in range(n - 1):
		if s[i] == s[i + 1] == '0' and i - lw > 1:
			lw = i
			count += 1
		elif s[i] == '1':
			lw = i
	if s[-2] == s[-1] == '0' and n - 1 - lw > 1:
		print(count + 1)
	else:
		print(count)
